<?php namespace App\Filament\Resources\ScholarshipCommissionResource\RelationManagers;
use Filament\Forms;use Filament\Resources\Form;use Filament\Resources\RelationManagers\RelationManager;use Filament\Resources\Table;use Filament\Tables;use Illuminate\Support\Facades\DB;
class DecisionsRelationManager extends RelationManager{protected static string $relationship='decisions';protected static ?string $title='Решения по студентам';
public static function form(Form $f):Form{return $f->schema([Forms\Components\Select::make('student_id')->label('Студент')->options(fn()=>DB::table('students')->where('status','active')->orderBy('last_name')->get()->mapWithKeys(fn($s)=>[$s->id=>trim($s->last_name.' '.$s->first_name)]))->searchable()->required(),Forms\Components\Select::make('type')->label('Вид')->options(['academic'=>'Академическая','social'=>'Социальная','named'=>'Именная','material_aid'=>'Материальная помощь'])->required(),Forms\Components\TextInput::make('amount')->label('Сумма')->numeric(),Forms\Components\DatePicker::make('starts_on')->label('С'),Forms\Components\DatePicker::make('ends_on')->label('По'),Forms\Components\Select::make('decision')->label('Решение')->options(['assigned'=>'Назначить','denied'=>'Отказать','stopped'=>'Прекратить'])->required(),Forms\Components\Textarea::make('basis')->label('Основание')]);}
public static function table(Table $t):Table{return $t->columns([Tables\Columns\TextColumn::make('student_id')->label('Студент')->formatStateUsing(fn($id)=>($s=DB::table('students')->where('id',$id)->first())?trim($s->last_name.' '.$s->first_name):'—'),Tables\Columns\BadgeColumn::make('type')->label('Вид'),Tables\Columns\TextColumn::make('amount')->label('Сумма'),Tables\Columns\BadgeColumn::make('decision')->label('Решение'),Tables\Columns\TextColumn::make('starts_on')->label('С')->date('d.m.Y')])->headerActions([Tables\Actions\CreateAction::make()->label('Добавить решение')])->actions([Tables\Actions\EditAction::make()]);}}
